// Round 3, wood-B: writes gen/r3b_lines.js (lines 65-110, stanzas 8-11, frames 3962-6276) from source/lines.json.
// Run from the project folder:   node js/woodcut/r3b-make-lyrics.mjs
// The output quotes the lyric, so it lives under gen/ (gitignored). Never edit the generated file by hand.
import fs from 'fs';
const d = JSON.parse(fs.readFileSync('source/lines.json', 'utf8'));
const I0 = 65, I1 = 110;
const lines = d.lines.filter(l => l.i >= I0 && l.i <= I1).map(l => ({ i: l.i, text: l.text, s: l.s, e: l.e, approx: !!l.approx, words: l.words.map(w => ({ w: w.w, s: w.s, e: w.e })) }));
for (const l of lines) if (l.words.map(w => w.w).join(' ') !== l.text) throw new Error('word list does not rebuild line ' + l.i);
if (lines.length !== I1 - I0 + 1) throw new Error('missing lines');
fs.mkdirSync('gen', { recursive: true });
fs.writeFileSync('gen/r3b_lines.js', '// GENERATED by js/woodcut/r3b-make-lyrics.mjs from source/lines.json (' + d.sha256.slice(0, 12) + '). Do not edit.\nconst r3bLY = ' + JSON.stringify(lines) + ';\n');
console.log(lines.length, 'lines', lines[0].i, '-', lines[lines.length - 1].i);
